import React from 'react';
import { Outlet, Link, useNavigate } from 'react-router-dom';
import API from '../api/axiosClient';
import { FaWallet, FaCashRegister, FaSignOutAlt, FaUserPlus, FaSignInAlt } from 'react-icons/fa';

export default function Layout({ user, setUser }) {
    const navigate = useNavigate();

    const handleLogout = async () => {
        try {
            await API.post('/auth/logout');
            setUser(null);
            navigate('/login');
        } catch (err) {
            console.error('Logout failed', err);
        }
    };

    return (
        <div className="min-h-screen bg-gray-900 text-white flex flex-col">
            {/* Persistent Professional Navbar */}
            <header className="bg-gray-800 border-b border-gray-700 px-8 py-4 flex justify-between items-center shadow-md">
                <Link to="/" className="font-bold text-xl flex items-center gap-2">
                    <span className="text-indigo-400">Loyalty</span>Mesh
                </Link>

                <nav className="flex items-center gap-6 text-sm font-medium">
                    {user ? ( 
                        <>
                            {user.role === 'customer' && (
                                <Link to="/customer" className="hover:text-indigo-400 flex items-center gap-1.5 transition">
                                    <FaWallet /> Dashboard
                                </Link>
                            )}
                            {( user.role === 'admin') && (
                                <Link to="/worker" className="hover:text-indigo-400 flex items-center gap-1.5 transition">
                                    <FaCashRegister /> Terminal
                                </Link>
                            )}
                            <div className="flex items-center gap-3 pl-4 border-l border-gray-700">
                                <span className="text-gray-400">Hi, <strong className="text-white">{user.name}</strong></span>
                                <button 
                                    onClick={handleLogout}
                                    className="bg-red-600/80 hover:bg-red-600 px-3 py-1.5 rounded-lg flex items-center gap-1.5 transition"
                                >
                                    <FaSignOutAlt /> Logout
                                </button>
                            </div>
                        </>
                    ) : (
                        <div className="flex items-center gap-4">
                            <Link to="/login" className="hover:text-indigo-400 flex items-center gap-1.5 transition">
                                <FaSignInAlt /> Login
                            </Link>
                            <Link to="/register" className="bg-indigo-600 hover:bg-indigo-500 px-4 py-2 rounded-lg flex items-center gap-1.5 transition font-semibold">
                                <FaUserPlus /> Register
                            </Link>
                        </div>
                    )}
                </nav>
            </header>

            {/* Main Dynamic View Outlet */}
            <main className="flex-1 p-8 max-w-7xl mx-auto w-full">
                <Outlet />
            </main>
        </div>
    );
}
